            v = grid[source_row][c]
            if v != 0 and v != shape_colour:
                source_items.append((v, c))

    # ------------------------------------------------------------------
    # 5. Build the output grid: start with zeros, then restore the shape
    out = [[0] * cols for _ in range(rows)]
    for (r, c) in shape_cells:
        out[r][c] = shape_colour

    # ------------------------------------------------------------------
    # 6. Place the source numbers into the shape
    for value, src_col in source_items:
        # find the nearest shape column that is strictly left of the source
        candidates = [col for col in shape_cols if col < src_col]
        if candidates:
            target_col = max(candidates)
        else:
            # no column on the left – use the nearest on the right
            candidates = [col for col in shape_cols if col > src_col]
            if candidates:
                target_col = min(candidates)
            else:
                continue          # should never happen

        # replace every shape cell in that column with the source value
        for (r, c) in shape_cells:
